Path regionPath(List<String> rings) {
  final path = Path()..fillType = PathFillType.evenOdd;
  for (final ring in rings) {
    path.addPolygon(
      ring.split(' ').map((point) {
        final pair = point.split(',');
        return Offset(double.parse(pair.first), double.parse(pair.last));
      }).toList(),
      true,
    );
  }
  return path;
}

